package org.apache.commons.codec;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class StringEncoderComparatorTest {

    @Test
    public void testConstructorWithNullEncoder() {
        try {
            new StringEncoderComparator(null);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            assertEquals("stringEncoder", e.getMessage());
        }
    }

    @Test
    public void testCompareWithNullEncoder() {
        StringEncoderComparator comparator = new StringEncoderComparator();
        assertEquals(0, comparator.compare("test1", "test2"));
    }

    @Test
    public void testCompareWithValidEncoder() throws EncoderException {
        StringEncoder encoder = mock(StringEncoder.class);
        when(encoder.encode("test1")).thenReturn("encoded1");
        when(encoder.encode("test2")).thenReturn("encoded2");

        StringEncoderComparator comparator = new StringEncoderComparator(encoder);
        assertEquals(0, comparator.compare("test1", "test2"));
    }

    @Test
    public void testCompareWithEncoderException() throws EncoderException {
        StringEncoder encoder = mock(StringEncoder.class);
        when(encoder.encode("test1")).thenThrow(new EncoderException("Test exception"));
        when(encoder.encode("test2")).thenReturn("encoded2");

        StringEncoderComparator comparator = new StringEncoderComparator(encoder);
        assertEquals(0, comparator.compare("test1", "test2"));
    }

    @Test
    public void testCompareWithNonStringInput() throws EncoderException {
        StringEncoder encoder = mock(StringEncoder.class);
