package org.apache.commons.codec.binary;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.apache.commons.codec.CodecPolicy;
import org.junit.Test;

public class Base16Test {

    @Test
    public void testEncodeDecode() {
        Base16 codec = new Base16();
        byte[] data = "Hello World".getBytes();
        byte[] encoded = codec.encode(data);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(data, decoded);
    }

    @Test
    public void testEncodeDecodeLowerCase() {
        Base16 codec = new Base16(true);
        byte[] data = "Hello World".getBytes();
        byte[] encoded = codec.encode(data);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(data, decoded);
    }

    @Test
    public void testEncodeEmpty() {
        Base16 codec = new Base16();
        byte[] data = new byte[0];
        byte[] encoded = codec.encode(data);
        assertArrayEquals(data, encoded);
    }

    @Test
    public void testDecodeEmpty() {
        Base16 codec = new Base16();
        byte[] data = new byte[0];
        byte[] decoded = codec.decode(data);
        assertArrayEquals(data, decoded);
    }

    @Test
    public void testEncodeDecodeWithBuilder() {
        Base16 codec = Base16.builder().setLowerCase(true).get();
        byte[] data = "Hello World".getBytes();
        byte[] encoded = codec.encode(data);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(data, decoded);
    }

    @Test
    public void testEncodeDecodeWithStrictPolicy() {
        Base16 codec = Base16.builder().setDecodingPolicy(CodecPolicy.STRICT).get();
        byte[] data = "Hello World".getBytes();
        byte[] encoded = codec.encode(data);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(data, decoded);
    }

    @Test
    public void testIsInAlphabet() {
        Base16 codec = new Base16();
        assertTrue(codec.isInAlphabet((byte) 'A'));
        assertTrue(codec.isInAlphabet((byte) 'a'));
        assertTrue(codec.isInAlphabet((byte) '0'));
        assertFalse(codec.isInAlphabet((byte) 'G'));
        assertFalse(codec.isInAlphabet((byte) 'g'));
        assertFalse(codec.isInAlphabet((byte) '9'));
    }

    @Test
    public void testEncodeDecodeWithCustomTable() {
        byte[] customTable = {'A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L', 'M', 'N', 'O', 'P'};
        Base16 codec = Base16.builder().setEncodeTable(customTable).get();
        byte[] data = {0x01, 0x02, 0x03};
        byte[] encoded = codec.encode(data);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(data, decoded);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testInvalidEncodeTable() {
        byte[] invalidTable = {'A', 'A', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L', 'M', 'N', 'O', 'P'};
        Base16.builder().setEncodeTable(invalidTable).get();
    }

    @Test
    public void testEncodeDecodePartialBlock() {
        Base16 codec = new Base16();
        byte[] data = {0x01};
        byte[] encoded = codec.encode(data);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(data, decoded);
    }

    @Test
    public void testEncodeDecodeWithPadding() {
        Base16 codec = new Base16();
        byte[] data = {0x01, 0x02, 0x03, 0x04, 0x05};
        byte[] encoded = codec.encode(data);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(data, decoded);
    }

    @Test
    public void testEncodeDecodeWithSpecialCharacters() {
        Base16 codec = new Base16();
        byte[] data = {0x00, 0xFF, 0x7F, 0x80};
        byte[] encoded = codec.encode(data);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(data, decoded);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testDecodeInvalidCharacter() {
        Base16 codec = new Base16();
        byte[] invalidData = "G".getBytes();
        codec.decode(invalidData);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testDecodeTrailingCharacterStrict() {
        Base16 codec = Base16.builder().setDecodingPolicy(CodecPolicy.STRICT).get();
        byte[] invalidData = "1".getBytes();
        codec.decode(invalidData);
    }

    @Test
    public void testDecodeTrailingCharacterLenient() {
        Base16 codec = new Base16();
        byte[] invalidData = "1".getBytes();
        byte[] decoded = codec.decode(invalidData);
        assertArrayEquals(new byte[0], decoded);
    }
}

