@RunWith(MockitoJUnitRunner.class)
public class Base16OutputStreamTest {

    @Mock
    private OutputStream mockOutputStream;

    @Test
    public void testBuilder() {
        Builder builder = Base16OutputStream.builder();
        assertEquals(true, builder.getEncode());
    }

    @Test
    public void testConstructorWithOutputStream() throws IOException {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Base16OutputStream base16OutputStream = new Base16OutputStream(outputStream);

        byte[] input = {0x01, 0x02, 0x03};
        base16OutputStream.write(input);
        base16OutputStream.flush();
        base16OutputStream.close();

        byte[] expected = "010203".getBytes();
        assertArrayEquals(expected, outputStream.toByteArray());
    }

    @Test
    public void testConstructorWithOutputStreamAndEncode() throws IOException {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Base16OutputStream base16OutputStream = new Base16OutputStream(outputStream, false);

        byte[] input = "010203".getBytes();
        base16OutputStream.write(input);
        base16OutputStream.flush();
        base16OutputStream.close();

        byte[] expected = {0x01, 0x02, 0x03};
        assertArrayEquals(expected, outputStream.toByteArray());
    }

    @Test
    public void testConstructorWithOutputStreamEncodeAndLowerCase() throws IOException {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Base16OutputStream base16OutputStream = new Base16OutputStream(outputStream, true, true);

        byte[] input = {0x01, 0x02, 0x03};
        base16OutputStream.write(input);
        base16OutputStream.flush();
        base16OutputStream.close();

        byte[] expected = "010203".getBytes();
        assertArrayEquals(expected, outputStream.toByteArray());
    }

