    public void testConstructorWithOutputStreamEncodeLowerCaseAndPolicy() throws IOException {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Base16OutputStream base16OutputStream = new Base16OutputStream(outputStream, true, true, CodecPolicy.STRICT);

        byte[] input = {0x01, 0x02, 0x03};
        base16OutputStream.write(input);
        base16OutputStream.flush();
        base16OutputStream.close();

        byte[] expected = "010203".getBytes();
        assertArrayEquals(expected, outputStream.toByteArray());
    }

    @Test
    public void testWriteByteArray() throws IOException {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Base16OutputStream base16OutputStream = new Base16OutputStream(outputStream);

        byte[] input = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06};
        base16OutputStream.write(input);
        base16OutputStream.flush();
        base16OutputStream.close();

        byte[] expected = "010203040506".getBytes();
        assertArrayEquals(expected, outputStream.toByteArray());
    }

    @Test
    public void testWriteByteArrayWithOffsetAndLength() throws IOException {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Base16OutputStream base16OutputStream = new Base16OutputStream(outputStream);

        byte[] input = {0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07};
        base16OutputStream.write(input, 2, 4);
        base16OutputStream.flush();
        base16OutputStream.close();

        byte[] expected = "02030405".getBytes();
        assertArrayEquals(expected, outputStream.toByteArray());
    }

    @Test
    public void testWriteByte() throws IOException {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Base16OutputStream base16OutputStream = new Base16OutputStream(outputStream);

        byte[] input = {0x01, 0x02, 0x03};
        for (byte b : input) {
            base16OutputStream.write(b);
        }
        base16OutputStream.flush();
        base16OutputStream.close();

        byte[] expected = "010203".getBytes();
        assertArrayEquals(expected, outputStream.toByteArray());
