package org.apache.commons.codec.binary;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;

import org.apache.commons.codec.CodecPolicy;
import org.junit.Test;

public class Base64InputStreamTest {

    private static final byte[] TEST_BYTES = "Hello World".getBytes();
    private static final String TEST_STRING = "Hello World";
    private static final String BASE64_ENCODED = "SGVsbG8gV29ybGQ=";

    @Test
    public void testBuilder() {
        Base64InputStream.Builder builder = Base64InputStream.builder();
        assertNotNull(builder);
    }

    @Test
    public void testConstructorWithInputStream() {
        InputStream input = new ByteArrayInputStream(TEST_BYTES);
        Base64InputStream stream = new Base64InputStream(input);
        assertNotNull(stream);
    }

    @Test
    public void testConstructorWithInputStreamAndEncode() {
        InputStream input = new ByteArrayInputStream(TEST_BYTES);
        Base64InputStream stream = new Base64InputStream(input, false);
        assertNotNull(stream);
    }

    @Test
    public void testConstructorWithInputStreamEncodeLineLengthLineSeparator() {
        InputStream input = new ByteArrayInputStream(TEST_BYTES);
        byte[] lineSeparator = "\r\n".getBytes();
        Base64InputStream stream = new Base64InputStream(input, false, 76, lineSeparator);
        assertNotNull(stream);
    }

    @Test
    public void testConstructorWithInputStreamEncodeLineLengthLineSeparatorPolicy() {
        InputStream input = new ByteArrayInputStream(TEST_BYTES);
        byte[] lineSeparator = "\r\n".getBytes();
        Base64InputStream stream = new Base64InputStream(input, false, 76, lineSeparator, CodecPolicy.LENIENT);
        assertNotNull(stream);
    }

    @Test
    public void testDecode() throws IOException {
        InputStream input = new ByteArrayInputStream(BASE64_ENCODED.getBytes());
        Base64InputStream stream = new Base64InputStream(input);
        byte[] decoded = new byte[TEST_BYTES.length];
        int bytesRead = stream.read(decoded);
        assertEquals(TEST_BYTES.length, bytesRead);
        assertArrayEquals(TEST_BYTES, decoded);
    }

    @Test
    public void testDecodeWithPadding() throws IOException {
        String paddedBase64 = "SGVsbG8gV29ybGQ======";
        InputStream input = new ByteArrayInputStream(paddedBase64.getBytes());
        Base64InputStream stream = new Base64InputStream(input);
        byte[] decoded = new byte[TEST_BYTES.length];
        int bytesRead = stream.read(decoded);
        assertEquals(TEST_BYTES.length, bytesRead);
        assertArrayEquals(TEST_BYTES, decoded);
    }

    @Test
    public void testDecodeWithStrictPolicy() throws IOException {
        String invalidBase64 = "SGVsbG8gV29ybGQ=" + (char) 0xFF; // Invalid character
        InputStream input = new ByteArrayInputStream(invalidBase64.getBytes());
        Base64InputStream stream = new Base64InputStream(input, false, 0, null, CodecPolicy.STRICT);
        try {
            byte[] decoded = new byte[TEST_BYTES.length];
            stream.read(decoded);
            fail("Expected IllegalArgumentException for invalid Base64 with strict policy");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Invalid character"));
        }
    }

    @Test
    public void testEncode() throws IOException {
        InputStream input = new ByteArrayInputStream(TEST_BYTES);
        Base64InputStream stream = new Base64InputStream(input, true);
        byte[] encoded = new byte[BASE64_ENCODED.length()];
        int bytesRead = stream.read(encoded);
        assertEquals(BASE64_ENCODED.length(), bytesRead);
        assertArrayEquals(BASE64_ENCODED.getBytes(), encoded);
    }

    @Test
    public void testReadSingleByte() throws IOException {
        InputStream input = new ByteArrayInputStream(TEST_BYTES);
        Base64InputStream stream = new Base64InputStream(input);
        for (byte b : TEST_BYTES) {
            int read = stream.read();
            assertEquals(b & 0xFF, read);
        }
        assertEquals(-1, stream.read());
    }

    @Test
    public void testReadWithOffset() throws IOException {
        InputStream input = new ByteArrayInputStream(TEST_BYTES);
        Base64InputStream stream = new Base64InputStream(input);
        byte[] buffer = new byte[TEST_BYTES.length];
        int bytesRead = stream.read(buffer, 0, TEST_BYTES.length);
        assertEquals(TEST_BYTES.length, bytesRead);
        assertArrayEquals(TEST_BYTES, buffer);
    }

    @Test
    public void testReadWithOffsetAndLength() throws IOException {
        InputStream input = new ByteArrayInputStream(TEST_BYTES);
        Base64InputStream stream = new Base64InputStream(input);
        byte[] buffer = new byte[TEST_BYTES.length / 2];
        int bytesRead = stream.read(buffer, 0, buffer.length);
        assertEquals(buffer.length, bytesRead);
        assertArrayEquals(TEST_BYTES, 0, buffer.length, buffer, 0, buffer.length);
    }

    @Test
    public void testReadWithInvalidParameters() throws IOException {
        InputStream input = new ByteArrayInputStream(TEST_BYTES);
        Base64InputStream stream = new Base64InputStream(input);
        try {
            stream.read(null, 0, 0);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // Expected
        }
        try {
            stream.read(new byte[10], -1, 0);
            fail("Expected IndexOutOfBoundsException");
        } catch (IndexOutOfBoundsException e) {
            // Expected
        }
        try {
            stream.read(new byte[10], 0, -1);
            fail("Expected IndexOutOfBoundsException");
        } catch (IndexOutOfBoundsException e) {
            // Expected
        }
        try {
            stream.read(new byte[10], 10, 1);
            fail("Expected IndexOutOfBoundsException");
        } catch (IndexOutOfBoundsException e) {
            // Expected
        }
    }
}

