        Base64OutputStream base64OutputStream = new Base64OutputStream(outputStream);

        byte[] input = "Hello World".getBytes();
        base64OutputStream.write(input);
        base64OutputStream.flush();
        base64OutputStream.close();

        byte[] expected = "SGVsbG8gV29ybGQ=".getBytes();
        assertArrayEquals(expected, outputStream.toByteArray());
    }

    @Test
    public void testWriteWithInvalidBase64() throws IOException {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Base64OutputStream base64OutputStream = new Base64OutputStream(outputStream, false);

        byte[] input = "SGVsbG8gV29ybGQ!".getBytes(); // Invalid character at end
        try {
            base64OutputStream.write(input);
            base64OutputStream.close();
        } catch (IllegalArgumentException e) {
            // Expected exception for invalid Base64
            assertTrue(e.getMessage().contains("Illegal base64 character"));
        }

        // Verify output is still correct for valid part
        byte[] expected = "Hello World".getBytes();
        assertArrayEquals(expected, outputStream.toByteArray());
    }

    @Test
    public void testWriteWithPartialBase64() throws IOException {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Base64OutputStream base64OutputStream = new Base64OutputStream(outputStream, false);

        byte[] input = "SGVsbG8gV29ybGQ".getBytes(); // Missing padding
        base64OutputStream.write(input);
        base64OutputStream.close();

        byte[] expected = "Hello World".getBytes();
        assertArrayEquals(expected, outputStream.toByteArray());
    }

    @Test
    public void testWriteWithCustomPadding() throws IOException {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Base64OutputStream base64OutputStream = Base64OutputStream.builder()
                .setOutputStream(outputStream)
                .setEncode(true)
                .setBaseNCodec(Base64.builder().setPadding('*').get())
                .get();

        byte[] input = "Hello World".getBytes();
        base64OutputStream.write(input);
        base64OutputStream.close();

        byte[] expected = "SGVsbG8gV29ybGQ**".getBytes();
        assertArrayEquals(expected, outputStream.toByteArray());
    }

    @Test
    public void testWriteWithURLSafeEncoding() throws IOException {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Base64OutputStream base64OutputStream = Base64OutputStream.builder()
                .setOutputStream(outputStream)
                .setEncode(true)
                .setBaseNCodec(Base64.builder().setEncodeTableRaw(Base64.URL_SAFE_ENCODE_TABLE).get())
                .get();

        byte[] input = "Hello World".getBytes();
        base64OutputStream.write(input);
        base64OutputStream.close();

        byte[] expected = "SGVsbG8gV29ybGQ=".getBytes();
        assertArrayEquals(expected, outputStream.toByteArray());
    }

    @Test
    public void testWriteWithLargeInput() throws IOException {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Base64OutputStream base64OutputStream = new Base64OutputStream(outputStream);

        byte[] input = new byte[1024 * 1024]; // 1MB input
        new Random().nextBytes(input);

        base64OutputStream.write(input);
