    public void testIsStrictDecoding() throws Exception {
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(new ByteArrayInputStream(new byte[0]), new Base16(), false);
        assertFalse(stream.isStrictDecoding());
        input.close();
    }

