    public void testMarkSupported() throws Exception {
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(new ByteArrayInputStream(new byte[0]), new Base16(), false);
        assertFalse(stream.markSupported());
    }

    @Test
    public void testReadSingleByte() throws Exception {
        byte[] data = {0x31, 0x32, 0x33}; // "123"
        InputStream input = new ByteArrayInputStream(data);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);

        assertEquals('1', stream.read());
        assertEquals('2', stream.read());
        assertEquals('3', stream.read());
        assertEquals(EOF, stream.read());
        input.close();
    }

