        InputStream input = new ByteArrayInputStream(data);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);

        byte[] buffer = new byte[3];
        int read = stream.read(buffer, 0, 3);
        assertEquals(3, read);
        assertArrayEquals(data, buffer);
        input.close();
    }

    @Test
    public void testReadWithOffsetAndLength() throws Exception {
        byte[] data = {0x31, 0x32, 0x33, 0x34, 0x35}; // "12345"
        InputStream input = new ByteArrayInputStream(data);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);

        byte[] buffer = new byte[5];
        int read = stream.read(buffer, 1, 3);
        assertEquals(3, read);
        assertArrayEquals(new byte[]{0, 0x32, 0x33, 0x34, 0}, buffer);
        input.close();
    }

