        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);
        byte[] buffer = new byte[10];
        stream.read(buffer, -1, 10);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testReadWithInvalidLength() throws Exception {
        InputStream input = new ByteArrayInputStream(new byte[0]);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);
        byte[] buffer = new byte[10];
        stream.read(buffer, 0, -1);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testReadWithInvalidBufferSize() throws Exception {
        InputStream input = new ByteArrayInputStream(new byte[0]);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);
        byte[] buffer = new byte[10];
        stream.read(buffer, 5, 6);
    }

    @Test
    public void testSkip() throws Exception {
        byte[] data = {0x31, 0x32, 0x33, 0x34, 0x35}; // "12345"
        InputStream input = new ByteArrayInputStream(data);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);

        long skipped = stream.skip(2);
        assertEquals(2, skipped);

        byte[] buffer = new byte[3];
        int read = stream.read(buffer, 0, 3);
        assertEquals(3, read);
        assertArrayEquals(new byte[]{0x33, 0x34, 0x35}, buffer);
        input.close();
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSkipWithNegativeLength() throws Exception {
        InputStream input = new ByteArrayInputStream(new byte[0]);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);
        stream.skip(-1);
    }

    @Test
    public void testResetThrowsIOException() throws Exception {
        InputStream input = new ByteArrayInputStream(new byte[0]);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);
        try {
            stream.reset();
            fail("Expected IOException");
        } catch (IOException e) {
            assertEquals("mark/reset not supported", e.getMessage());
        }
    }

    @Test
    public void testMarkDoesNothing() throws Exception {
        InputStream input = new ByteArrayInputStream(new byte[0]);
        BaseNCodecInputStream<Base16, Base16InputStream, Base16InputStream.Builder> stream =
            new BaseNCodecInputStream<>(input, new Base16(), false);
        stream.mark(100);
        // No exception should be thrown
    }
}

