    public void testFromAsciiByteArrayMultipleBytes() {
        byte[] input = {'1', '0', '1', '1', '0', '0', '1', '0'};
        byte[] result = BinaryCodec.fromAscii(input);
        assertArrayEquals(new byte[]{0xA2}, result);
