        Mockito.verify(DigestUtils, Mockito.atLeastOnce()).isAvailable(Mockito.anyString());
    }

    @Test
    public void testRunWithValidAlgorithmAndFile() throws IOException {
        String[] args = {"MD5", "test.txt"};
        Digest digest = new Digest(args);
        Mockito.when(DigestUtils.getDigest("MD5")).thenReturn(mockMessageDigest);
        Mockito.when(mockMessageDigest.digest()).thenReturn(new byte[]{0x01, 0x02, 0x03});

