        System.setOut(new java.io.PrintStream(new java.io.ByteArrayOutputStream()));
        new Digest(new String[0]).println(prefix, digest);
        assertEquals(expected, System.out.toString().trim());

        // Reset System.out
        System.setOut(System.out);
    }

