        assertEquals(0xFFFF, crc16.init);
        assertArrayEquals(Crc16.getIbmSdlcTable(), crc16.table);
        assertEquals(0xFFFF, crc16.xorOut);
    }

    @Test
    public void testMaxim() {
        Crc16 crc16 = Crc16.maxim();
        assertEquals(0x0000, crc16.init);
        assertArrayEquals(Crc16.getMaximTable(), crc16.table);
        assertEquals(0xFFFF, crc16.xorOut);
    }

    @Test
    public void testMcrf4xx() {
