        assertEquals(0xFFFF, crc16.init);
        assertArrayEquals(Crc16.getNrsc5Table(), crc16.table);
        assertEquals(0x0000, crc16.xorOut);
    }

    @Test
    public void testUsb() {
        Crc16 crc16 = Crc16.usb();
        assertEquals(0xFFFF, crc16.init);
        assertArrayEquals(Crc16.getUsbTable(), crc16.table);
        assertEquals(0xFFFF, crc16.xorOut);
    }

    @Test
    public void testGetValue() {
        Crc16 crc16 = Crc16.builder().setInit(0x1234).setXorOut(0xABCD).table(new int[256]).get();
        assertEquals(0x1234 ^ 0xABCD, crc16.getValue());
    }

    @Test
    public void testReset() {
        Crc16 crc16 = Crc16.builder().setInit(0x1234).table(new int[256]).get();
        crc16.update((byte) 0x55);
        crc16.reset();
        assertEquals(0x1234, crc16.crc);
    }

    @Test
    public void testUpdateByte() {
        Crc16 crc16 = Crc16.builder().setInit(0x0000).table(Crc16.getArcTable()).get();
        crc16.update((byte) 0x00);
        assertEquals(0x0000, crc16.getValue());
        crc16.update((byte) 0x01);
        assertEquals(0xC0C1, crc16.getValue());
    }

    @Test
    public void testUpdateByteArray() {
        Crc16 crc16 = Crc16.builder().setInit(0x0000).table(Crc16.getArcTable()).get();
        byte[] data = {0x00, 0x01, 0x02, 0x03};
        crc16.update(data, 0, data.length);
        assertEquals(0xC701, crc16.getValue());
    }

    @Test
    public void testUpdateByteArrayWithOffset() {
        Crc16 crc16 = Crc16.builder().setInit(0x0000).table(Crc16.getArcTable()).get();
        byte[] data = {0x00, 0x01, 0x02, 0x03};
        crc16.update(data, 1, 2);
        assertEquals(0xC181, crc16.getValue());
    }

    @Test
    public void testToString() {
        Crc16 crc16 = Crc16.builder().setInit(0x1234).setXorOut(0xABCD).table(new int[256]).get();
        String expected = "Crc16 [init=0x1234, crc=0x1234, xorOut=0xABCD, crc^xorOut=0xB9C9]";
        assertEquals(expected, crc16.toString());
    }
}

