package org.apache.commons.codec.digest;

import org.junit.Test;
import static org.junit.Assert.*;

public class CryptTest {

    @Test
    public void testCryptWithNullSalt() {
        String password = "password";
        String result = Crypt.crypt(password);
        assertNotNull(result);
        assertTrue(result.startsWith(Sha2Crypt.SHA512_PREFIX));
        assertEquals(106, result.length());
    }

    @Test
    public void testCryptWithSha512Salt() {
        String password = "password";
        String salt = "$6$abcdefghijklmnop";
        String result = Crypt.crypt(password, salt);
        assertNotNull(result);
        assertTrue(result.startsWith(Sha2Crypt.SHA512_PREFIX));
        assertEquals(106, result.length());
    }

    @Test
    public void testCryptWithSha256Salt() {
        String password = "password";
        String salt = "$5$abcdefghijklmnop";
        String result = Crypt.crypt(password, salt);
        assertNotNull(result);
        assertTrue(result.startsWith(Sha2Crypt.SHA256_PREFIX));
        assertEquals(63, result.length());
    }

    @Test
    public void testCryptWithMd5Salt() {
        String password = "password";
        String salt = "$1$abcdefgh";
        String result = Crypt.crypt(password, salt);
        assertNotNull(result);
        assertTrue(result.startsWith(Md5Crypt.MD5_PREFIX));
        assertEquals(34, result.length());
    }

    @Test
    public void testCryptWithDesSalt() {
        String password = "password";
        String salt = "ab";
        String result = Crypt.crypt(password, salt);
        assertNotNull(result);
        assertEquals(13, result.length());
    }

    @Test
    public void testCryptWithInvalidSalt() {
        String password = "password";
        String invalidSalt = "invalid";
        try {
            Crypt.crypt(password, invalidSalt);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid salt value: invalid", e.getMessage());
        }
    }

    @Test
    public void testCryptWithByteArray() {
        byte[] passwordBytes = "password".getBytes();
        String result = Crypt.crypt(passwordBytes);
        assertNotNull(result);
        assertTrue(result.startsWith(Sha2Crypt.SHA512_PREFIX));
        assertEquals(106, result.length());
    }

    @Test
    public void testCryptWithByteArrayAndSalt() {
        byte[] passwordBytes = "password".getBytes();
        String salt = "$6$abcdefghijklmnop";
        String result = Crypt.crypt(passwordBytes, salt);
        assertNotNull(result);
        assertTrue(result.startsWith(Sha2Crypt.SHA512_PREFIX));
        assertEquals(106, result.length());
    }

    @Test
    public void testCryptWithEmptyPassword() {
        String password = "";
        String result = Crypt.crypt(password);
        assertNotNull(result);
        assertTrue(result.startsWith(Sha2Crypt.SHA512_PREFIX));
        assertEquals(106, result.length());
    }

