package org.apache.commons.codec.digest;

import static org.junit.Assert.*;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

@RunWith(MockitoJUnitRunner.class)
public class GitIdentifiersTest {

    @Mock
    private MessageDigest mockMessageDigest;

    @Test
    public void testBlobIdWithByteArray() throws NoSuchAlgorithmException {
        MessageDigest messageDigest = MessageDigest.getInstance("SHA-1");
        byte[] data = "test".getBytes();
        byte[] expected = messageDigest.digest(data);
        byte[] actual = GitIdentifiers.blobId(messageDigest, data);
        assertArrayEquals(expected, actual);
    }

    @Test
    public void testBlobIdWithInputStream() throws IOException, NoSuchAlgorithmException {
        MessageDigest messageDigest = MessageDigest.getInstance("SHA-1");
        byte[] data = "test".getBytes();
        ByteArrayInputStream inputStream = new ByteArrayInputStream(data);
        byte[] expected = messageDigest.digest(data);
        byte[] actual = GitIdentifiers.blobId(messageDigest, data.length, inputStream);
        assertArrayEquals(expected, actual);
    }

    @Test
    public void testTreeIdBuilderAddDirectory() {
        TreeIdBuilder builder = GitIdentifiers.treeIdBuilder(mockMessageDigest);
        TreeIdBuilder subBuilder = builder.addDirectory("subdir");
        assertNotNull(subBuilder);
        assertNotSame(builder, subBuilder);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testTreeIdBuilderAddDirectoryWithInvalidPath() {
        TreeIdBuilder builder = GitIdentifiers.treeIdBuilder(mockMessageDigest);
        builder.addDirectory("..");
    }

    @Test
    public void testTreeIdBuilderAddFile() throws IOException {
        TreeIdBuilder builder = GitIdentifiers.treeIdBuilder(mockMessageDigest);
        builder.addFile(FileMode.REGULAR, "file.txt", "content".getBytes());
        byte[] id = builder.get();
        assertNotNull(id);
    }

    @Test
    public void testTreeIdBuilderAddSymbolicLink() throws IOException {
        TreeIdBuilder builder = GitIdentifiers.treeIdBuilder(mockMessageDigest);
        builder.addSymbolicLink("link.txt", "target");
        byte[] id = builder.get();
        assertNotNull(id);
    }

    @Test
    public void testFileModeGet() throws IOException {
        Path tempDir = Files.createTempDirectory("test");
        Path file = Files.createFile(tempDir.resolve("file.txt"));
        assertEquals(FileMode.REGULAR, FileMode.get(file));

        Path execFile = Files.createFile(tempDir.resolve("exec.sh"));
        execFile.toFile().setExecutable(true);
        assertEquals(FileMode.EXECUTABLE, FileMode.get(execFile));

        Path symLink = Files.createSymbolicLink(tempDir.resolve("link.txt"), file);
        assertEquals(FileMode.SYMBOLIC_LINK, FileMode.get(symLink));

        Path subDir = Files.createDirectory(tempDir.resolve("subdir"));
        assertEquals(FileMode.DIRECTORY, FileMode.get(subDir));

        Files.deleteIfExists(execFile);
        Files.deleteIfExists(file);
        Files.deleteIfExists(symLink);
        Files.deleteIfExists(subDir);
        Files.deleteIfExists(tempDir);
    }

    @Test
    public void testDirectoryEntryComparison() {
        DirectoryEntry entry1 = new DirectoryEntry("file.txt", FileMode.REGULAR, new byte[20]);
        DirectoryEntry entry2 = new DirectoryEntry("file.txt", FileMode.REGULAR, new byte[20]);
        DirectoryEntry entry3 = new DirectoryEntry("subdir/", FileMode.DIRECTORY, new byte[20]);

        assertEquals(0, entry1.compareTo(entry2));
        assertTrue(entry1.compareTo(entry3) < 0);
        assertTrue(entry3.compareTo(entry1) > 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testDirectoryEntryWithInvalidName() {
        new DirectoryEntry("invalid/name.txt", FileMode.REGULAR, new byte[20]);
    }
}

