    public void testHmacWithString() {
        byte[] result = new HmacUtils(HmacAlgorithms.HMAC_MD5, TEST_KEY).hmac(TEST_VALUE);
        assertArrayEquals(result, new HmacUtils("HmacMD5", TEST_KEY).hmac(TEST_VALUE));
    }

