    public void testHmacWithByteBuffer() {
        ByteBuffer buffer = ByteBuffer.wrap(TEST_VALUE_BYTES);
        byte[] result = new HmacUtils(HmacAlgorithms.HMAC_MD5, TEST_KEY).hmac(buffer);
