package org.apache.commons.codec.digest;

import org.junit.Test;
import static org.junit.Assert.*;

public class MurmurHash2Test {

    @Test
    public void testHash32EmptyString() {
        assertEquals(0x9747b28c, MurmurHash2.hash32(""));
    }

    @Test
    public void testHash32SingleCharacter() {
        assertEquals(0x9747b28c ^ 0x61 ^ 0x61 * 0x5bd1e995, MurmurHash2.hash32("a"));
    }

    @Test
    public void testHash32WithSeed() {
        assertEquals(0x12345678, MurmurHash2.hash32("test".getBytes(), 4, 0x12345678));
    }

    @Test
    public void testHash32WithSubstring() {
        assertEquals(MurmurHash2.hash32("hello"), MurmurHash2.hash32("hello world", 0, 5));
    }

    @Test
    public void testHash64EmptyString() {
        assertEquals(0xe17a1465L, MurmurHash2.hash64(""));
    }

    @Test
    public void testHash64SingleCharacter() {
        assertEquals(0xe17a1465L ^ 0x61L ^ 0x61L * 0xc6a4a7935bd1e995L, MurmurHash2.hash64("a"));
    }

    @Test
    public void testHash64WithSeed() {
        assertEquals(0x12345678L, MurmurHash2.hash64("test".getBytes(), 4, 0x12345678));
    }

    @Test
    public void testHash64WithSubstring() {
        assertEquals(MurmurHash2.hash64("hello"), MurmurHash2.hash64("hello world", 0, 5));
    }

    @Test
    public void testHash32WithNullInput() {
        assertNull(MurmurHash2.hash32((String) null));
    }

    @Test
    public void testHash64WithNullInput() {
        assertNull(MurmurHash2.hash64((String) null));
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testHash32SubstringOutOfBounds() {
        MurmurHash2.hash32("short", 0, 10);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testHash64SubstringOutOfBounds() {
        MurmurHash2.hash64("short", 0, 10);
    }
}

