package org.apache.commons.codec.digest;

import org.junit.Test;
import static org.junit.Assert.*;

public class MurmurHash3Test {

    @Test
    public void testHash32EmptyArray() {
        byte[] emptyArray = new byte[0];
        int hash = MurmurHash3.hash32x86(emptyArray);
        assertEquals(0, hash);
    }

    @Test
    public void testHash32SingleByte() {
        byte[] singleByte = new byte[]{0x01};
        int hash = MurmurHash3.hash32x86(singleByte);
        assertEquals(0xcc9e2d51, hash);
    }

    @Test
    public void testHash32TwoBytes() {
        byte[] twoBytes = new byte[]{0x01, 0x02};
        int hash = MurmurHash3.hash32x86(twoBytes);
        assertEquals(0x1b873593, hash);
    }

    @Test
    public void testHash32ThreeBytes() {
        byte[] threeBytes = new byte[]{0x01, 0x02, 0x03};
        int hash = MurmurHash3.hash32x86(threeBytes);
        assertEquals(0x3c6ef372, hash);
    }

    @Test
    public void testHash32FourBytes() {
        byte[] fourBytes = new byte[]{0x01, 0x02, 0x03, 0x04};
        int hash = MurmurHash3.hash32x86(fourBytes);
        assertEquals(0x6b86b09a, hash);
    }

    @Test
    public void testHash32WithSeed() {
        byte[] data = new byte[]{0x01, 0x02, 0x03, 0x04};
        int hash = MurmurHash3.hash32x86(data, 0, data.length, 12345);
        assertEquals(0x6b86b09a ^ 12345, hash);
    }

    @Test
    public void testHash32WithOffset() {
        byte[] data = new byte[]{0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};
        int hash = MurmurHash3.hash32x86(data, 4, 4);
        assertEquals(0x6b86b09a, hash);
    }

    @Test
    public void testHash32WithNegativeBytes() {
        byte[] data = new byte[]{0x01, 0x02, (byte)0xFF, (byte)0xFE};
        int hash = MurmurHash3.hash32x86(data);
        assertEquals(0x3c6ef372, hash);
    }

    @Test
    public void testHash128EmptyArray() {
        byte[] emptyArray = new byte[0];
        long[] hash = MurmurHash3.hash128x64(emptyArray);
        assertEquals(0, hash[0]);
        assertEquals(0, hash[1]);
    }

    @Test
    public void testHash128SingleByte() {
        byte[] singleByte = new byte[]{0x01};
        long[] hash = MurmurHash3.hash128x64(singleByte);
        assertEquals(0x87c37b91114253d5L, hash[0]);
        assertEquals(0x4cf5ad432745937fL, hash[1]);
    }

    @Test
    public void testHash128WithSeed() {
        byte[] data = new byte[]{0x01, 0x02, 0x03, 0x04};
        long[] hash = MurmurHash3.hash128x64(data, 0, data.length, 12345);
        assertEquals(0x87c37b91114253d5L ^ 12345, hash[0]);
        assertEquals(0x4cf5ad432745937fL ^ 12345, hash[1]);
    }

    @Test
    public void testHash128WithOffset() {
        byte[] data = new byte[]{0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};
        long[] hash = MurmurHash3.hash128x64(data, 4, 4);
        assertEquals(0x87c37b91114253d5L, hash[0]);
        assertEquals(0x4cf5ad432745937fL, hash[1]);
    }

    @Test
    public void testHash128WithNegativeBytes() {
        byte[] data = new byte[]{0x01, 0x02, (byte)0xFF, (byte)0xFE};
        long[] hash = MurmurHash3.hash128x64(data);
        assertEquals(0x87c37b91114253d5L, hash[0]);
        assertEquals(0x4cf5ad432745937fL, hash[1]);
    }

    @Test
    public void testIncrementalHash32x86() {
        MurmurHash3.IncrementalHash32x86 incremental = new MurmurHash3.IncrementalHash32x86();
        incremental.start(12345);

        byte[] data = new byte[]{0x01, 0x02, 0x03, 0x04};
        incremental.add(data, 0, data.length);

        int hash = incremental.end();
        assertEquals(0x6b86b09a ^ 12345, hash);
    }

    @Test
    public void testIncrementalHash32x86WithMultipleAdds() {
        MurmurHash3.IncrementalHash32x86 incremental = new MurmurHash3.IncrementalHash32x86();
        incremental.start(12345);

        byte[] data1 = new byte[]{0x01, 0x02};
        byte[] data2 = new byte[]{0x03, 0x04};

        incremental.add(data1, 0, data1.length);
        incremental.add(data2, 0, data2.length);

        int hash = incremental.end();
        assertEquals(0x6b86b09a ^ 12345, hash);
    }

    @Test
    public void testIncrementalHash32x86WithPartialBlocks() {
        MurmurHash3.IncrementalHash32x86 incremental = new MurmurHash3.IncrementalHash32x86();
        incremental.start(12345);

        byte[] data = new byte[]{0x01, 0x02, 0x03};
        incremental.add(data, 0, data.length);

        int hash = incremental.end();
        assertEquals(0x3c6ef372 ^ 12345, hash);
    }
}

