package org.apache.commons.codec.digest;

import org.junit.Test;
import static org.junit.Assert.*;

public class XXHash32Test {

    @Test
    public void testDefaultConstructor() {
        XXHash32 xxHash32 = new XXHash32();
        assertEquals(0, xxHash32.getValue());
    }

    @Test
    public void testConstructorWithSeed() {
        XXHash32 xxHash32 = new XXHash32(12345);
        assertEquals(0, xxHash32.getValue());
    }

    @Test
    public void testUpdateWithEmptyArray() {
        XXHash32 xxHash32 = new XXHash32();
        xxHash32.update(new byte[0], 0, 0);
        assertEquals(0, xxHash32.getValue());
    }

    @Test
    public void testUpdateWithSingleByte() {
        XXHash32 xxHash32 = new XXHash32();
        xxHash32.update(new byte[]{0x01}, 0, 1);
        assertEquals(0x01000000L, xxHash32.getValue());
    }

    @Test
    public void testUpdateWithMultipleBytes() {
        XXHash32 xxHash32 = new XXHash32();
        byte[] data = new byte[]{0x01, 0x02, 0x03, 0x04};
        xxHash32.update(data, 0, data.length);
        assertEquals(0x04030201L, xxHash32.getValue());
    }

    @Test
    public void testUpdateWithPartialBlock() {
        XXHash32 xxHash32 = new XXHash32();
        byte[] data = new byte[]{0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07};
        xxHash32.update(data, 0, data.length);
        assertEquals(0x07060504L, xxHash32.getValue());
    }

    @Test
    public void testUpdateWithMultipleBlocks() {
        XXHash32 xxHash32 = new XXHash32();
        byte[] data = new byte[32];
        for (int i = 0; i < data.length; i++) {
            data[i] = (byte) (i + 1);
        }
        xxHash32.update(data, 0, data.length);
        assertEquals(0x00000000L, xxHash32.getValue());
    }

    @Test
    public void testUpdateWithInt() {
        XXHash32 xxHash32 = new XXHash32();
        xxHash32.update(0x01020304);
        assertEquals(0x04030201L, xxHash32.getValue());
    }

    @Test
    public void testReset() {
        XXHash32 xxHash32 = new XXHash32(12345);
        xxHash32.update(new byte[]{0x01, 0x02, 0x03});
        xxHash32.reset();
        assertEquals(0, xxHash32.getValue());
    }

    @Test
    public void testGetValueAfterUpdate() {
        XXHash32 xxHash32 = new XXHash32();
        byte[] data = new byte[]{0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};
        xxHash32.update(data, 0, data.length);
        long value = xxHash32.getValue();
        assertNotEquals(0, value);
    }

    @Test
    public void testUpdateWithNullArray() {
        XXHash32 xxHash32 = new XXHash32();
        try {
            xxHash32.update(null, 0, 0);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            assertTrue(true);
        }
    }

    @Test
    public void testUpdateWithNegativeLength() {
        XXHash32 xxHash32 = new XXHash32();
        try {
            xxHash32.update(new byte[10], 0, -1);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(true);
        }
    }

    @Test
    public void testUpdateWithInvalidOffset() {
        XXHash32 xxHash32 = new XXHash32();
