package org.apache.commons.codec.language;

import org.apache.commons.codec.EncoderException;
import org.junit.Test;

import static org.junit.Assert.*;

public class CaverphoneTest {

    @Test
    public void testEncodeString() {
        Caverphone caverphone = new Caverphone();
        assertEquals("A23", caverphone.encode("John"));
        assertEquals("A23", caverphone.encode("john"));
        assertEquals("A23", caverphone.encode("JOHN"));
        assertEquals("A23", caverphone.encode("jOhN"));
    }

    @Test
    public void testEncodeObject() throws EncoderException {
        Caverphone caverphone = new Caverphone();
        assertEquals("A23", caverphone.encode((Object)"John"));
    }

    @Test(expected = EncoderException.class)
    public void testEncodeNonStringObject() throws EncoderException {
        Caverphone caverphone = new Caverphone();
        caverphone.encode(123);
    }

    @Test
    public void testIsCaverphoneEqual() {
        Caverphone caverphone = new Caverphone();
        assertTrue(caverphone.isCaverphoneEqual("John", "john"));
        assertTrue(caverphone.isCaverphoneEqual("John", "JOHN"));
        assertFalse(caverphone.isCaverphoneEqual("John", "Jane"));
    }

    @Test
    public void testEmptyString() {
        Caverphone caverphone = new Caverphone();
        assertEquals("A23", caverphone.encode(""));
    }

    @Test
    public void testNullString() {
        Caverphone caverphone = new Caverphone();
        assertEquals("A23", caverphone.encode(null));
    }

    @Test
    public void testSpecialCharacters() {
        Caverphone caverphone = new Caverphone();
        assertEquals("A23", caverphone.encode("John123"));
        assertEquals("A23", caverphone.encode("John@"));
        assertEquals("A23", caverphone.encode("John#"));
    }

    @Test
    public void testLongString() {
        Caverphone caverphone = new Caverphone();
        String longString = "JohnDoeJohnDoeJohnDoeJohnDoeJohnDoe";
        assertEquals("A23", caverphone.encode(longString));
    }
}

