import org.apache.commons.codec.EncoderException;
import org.junit.Test;
import static org.junit.Assert.*;

public class ColognePhoneticTest {

    private final ColognePhonetic encoder = new ColognePhonetic();

    @Test
    public void testNullInput() {
        assertNull(encoder.encode(null));
    }

    @Test
    public void testEmptyString() {
        assertEquals("", encoder.encode(""));
    }

    @Test
    public void testNonStringInput() {
        try {
            encoder.encode(123);
            fail("Expected EncoderException");
        } catch (EncoderException e) {
            assertTrue(e.getMessage().contains("String"));
        }
    }

    @Test
    public void testBasicEncoding() {
        assertEquals("6050750206802", encoder.encode("Müller-Lüdenscheidt"));
        assertEquals("6050750206802", encoder.encode("MULLERLUDENSCHEIDT"));
        assertEquals("6050750206802", encoder.encode("MÜLLER-LÜDENSCHEIDT"));
    }

    @Test
    public void testVowels() {
        assertEquals("0", encoder.encode("A"));
        assertEquals("0", encoder.encode("E"));
        assertEquals("0", encoder.encode("I"));
        assertEquals("0", encoder.encode("J"));
        assertEquals("0", encoder.encode("O"));
        assertEquals("0", encoder.encode("U"));
        assertEquals("0", encoder.encode("Y"));
    }

    @Test
    public void testConsonants() {
        assertEquals("1", encoder.encode("B"));
        assertEquals("1", encoder.encode("P"));
        assertEquals("2", encoder.encode("D"));
        assertEquals("2", encoder.encode("T"));
        assertEquals("3", encoder.encode("F"));
        assertEquals("3", encoder.encode("V"));
        assertEquals("3", encoder.encode("W"));
        assertEquals("4", encoder.encode("G"));
        assertEquals("4", encoder.encode("K"));
        assertEquals("4", encoder.encode("Q"));
        assertEquals("5", encoder.encode("L"));
        assertEquals("6", encoder.encode("M"));
        assertEquals("6", encoder.encode("N"));
        assertEquals("7", encoder.encode("R"));
        assertEquals("8", encoder.encode("S"));
        assertEquals("8", encoder.encode("Z"));
    }

    @Test
    public void testSpecialCases() {
        assertEquals("48", encoder.encode("X"));
        assertEquals("8", encoder.encode("C"));
        assertEquals("-", encoder.encode("H"));
    }

    @Test
    public void testIsEncodeEqual() {
        assertTrue(encoder.isEncodeEqual("Müller", "Muller"));
        assertTrue(encoder.isEncodeEqual("Lüdenscheidt", "Ludenscheidt"));
        assertFalse(encoder.isEncodeEqual("Müller", "Schmidt"));
    }

    @Test
    public void testPreprocess() {
        assertEquals("MULLER", encoder.encode("Müller"));
        assertEquals("LUDENSCHEIDT", encoder.encode("Lüdenscheidt"));
        assertEquals("SS", encoder.encode("ß"));
    }

    @Test
    public void testMultipleConsecutiveCodes() {
        assertEquals("65752682", encoder.encode("MüllerLüdenscheidt"));
    }

    @Test
    public void testNonAlphabeticCharacters() {
        assertEquals("6050750206802", encoder.encode("Müller-Lüdenscheidt"));
        assertEquals("6050750206802", encoder.encode("Müller-Lüdenscheidt!"));
        assertEquals("6050750206802", encoder.encode("Müller-Lüdenscheidt 123"));
    }
}

