package org.apache.commons.codec.language;

import org.apache.commons.codec.EncoderException;
import org.junit.Test;
import static org.junit.Assert.*;

public class DaitchMokotoffSoundexTest {

    @Test
    public void testEncodeNull() {
        DaitchMokotoffSoundex soundex = new DaitchMokotoffSoundex();
        assertNull(soundex.encode((String) null));
    }

    @Test
    public void testEncodeEmptyString() {
        DaitchMokotoffSoundex soundex = new DaitchMokotoffSoundex();
        assertEquals("", soundex.encode(""));
    }

    @Test
    public void testEncodeNonStringObject() {
        DaitchMokotoffSoundex soundex = new DaitchMokotoffSoundex();
        try {
            soundex.encode(123);
            fail("Expected EncoderException");
        } catch (EncoderException e) {
            assertEquals("Parameter supplied to DaitchMokotoffSoundex encode is not of type java.lang.String", e.getMessage());
        }
    }

    @Test
    public void testEncodeBasic() {
        DaitchMokotoffSoundex soundex = new DaitchMokotoffSoundex();
        assertEquals("000000", soundex.encode("A"));
        assertEquals("000000", soundex.encode("B"));
        assertEquals("000000", soundex.encode("C"));
        assertEquals("000000", soundex.encode("D"));
        assertEquals("000000", soundex.encode("E"));
    }

    @Test
    public void testEncodeWithFolding() {
        DaitchMokotoffSoundex soundex = new DaitchMokotoffSoundex(true);
        assertEquals("000000", soundex.encode("À"));
        assertEquals("000000", soundex.encode("É"));
        assertEquals("000000", soundex.encode("Ï"));
        assertEquals("000000", soundex.encode("Ô"));
        assertEquals("000000", soundex.encode("Ù"));
    }

    @Test
    public void testEncodeWithoutFolding() {
        DaitchMokotoffSoundex soundex = new DaitchMokotoffSoundex(false);
        assertEquals("000000", soundex.encode("À"));
        assertEquals("000000", soundex.encode("É"));
        assertEquals("000000", soundex.encode("Ï"));
        assertEquals("000000", soundex.encode("Ô"));
        assertEquals("000000", soundex.encode("Ù"));
    }

    @Test
    public void testEncodeComplexName() {
        DaitchMokotoffSoundex soundex = new DaitchMokotoffSoundex();
        assertEquals("097400", soundex.encode("Auerbach"));
    }

    @Test
    public void testSoundexWithBranching() {
        DaitchMokotoffSoundex soundex = new DaitchMokotoffSoundex();
        assertEquals("097400|097500", soundex.soundex("Auerbach"));
    }

    @Test
    public void testSoundexWithBranchingEmptyString() {
        DaitchMokotoffSoundex soundex = new DaitchMokotoffSoundex();
        assertEquals("", soundex.soundex(""));
    }

    @Test
    public void testSoundexWithBranchingNull() {
        DaitchMokotoffSoundex soundex = new DaitchMokotoffSoundex();
        assertNull(soundex.soundex(null));
    }

    @Test
    public void testSoundexWithBranchingSingleCharacter() {
        DaitchMokotoffSoundex soundex = new DaitchMokotoffSoundex();
        assertEquals("000000", soundex.soundex("A"));
    }

    @Test
    public void testSoundexWithBranchingSpecialCharacters() {
        DaitchMokotoffSoundex soundex = new DaitchMokotoffSoundex();
        assertEquals("000000", soundex.soundex("!@#$%^&*()"));
    }

    @Test
    public void testSoundexWithBranchingWhitespace() {
        DaitchMokotoffSoundex soundex = new DaitchMokotoffSoundex();
        assertEquals("000000", soundex.soundex("   "));
    }
}

