import org.junit.Test;
import static org.junit.Assert.*;

public class DoubleMetaphoneTest {

    @Test
    public void testCleanInput() {
        DoubleMetaphone dm = new DoubleMetaphone();
        assertNull(dm.cleanInput(null));
        assertNull(dm.cleanInput(""));
        assertNull(dm.cleanInput("   "));
        assertEquals("HELLO", dm.cleanInput("hello"));
        assertEquals("HELLO", dm.cleanInput("  hello  "));
    }

    @Test
    public void testDoubleMetaphone() {
        DoubleMetaphone dm = new DoubleMetaphone();
        assertNull(dm.doubleMetaphone(null));
        assertEquals("", dm.doubleMetaphone(""));
        assertEquals("T", dm.doubleMetaphone("T"));
        assertEquals("T", dm.doubleMetaphone("t"));
        assertEquals("T", dm.doubleMetaphone("  t  "));
        assertEquals("T", dm.doubleMetaphone("Tt"));
    }

    @Test
    public void testDoubleMetaphoneWithAlternate() {
        DoubleMetaphone dm = new DoubleMetaphone();
        assertNull(dm.doubleMetaphone(null, true));
        assertEquals("", dm.doubleMetaphone("", true));
        assertEquals("T", dm.doubleMetaphone("T", true));
        assertEquals("T", dm.doubleMetaphone("t", true));
        assertEquals("T", dm.doubleMetaphone("  t  ", true));
        assertEquals("T", dm.doubleMetaphone("Tt", true));
    }

    @Test
    public void testEncodeObject() {
        DoubleMetaphone dm = new DoubleMetaphone();
        assertNull(dm.encode(null));
        assertEquals("", dm.encode(""));
        assertEquals("T", dm.encode("T"));
        assertEquals("T", dm.encode("t"));
        assertEquals("T", dm.encode("  t  "));
        assertEquals("T", dm.encode("Tt"));
    }

    @Test(expected = EncoderException.class)
    public void testEncodeNonString() {
        DoubleMetaphone dm = new DoubleMetaphone();
        dm.encode(123);
    }

    @Test
    public void testIsDoubleMetaphoneEqual() {
        DoubleMetaphone dm = new DoubleMetaphone();
        assertTrue(dm.isDoubleMetaphoneEqual("hello", "hello"));
        assertFalse(dm.isDoubleMetaphoneEqual("hello", "world"));
        assertTrue(dm.isDoubleMetaphoneEqual("hello", "HELLO"));
        assertTrue(dm.isDoubleMetaphoneEqual("hello", "HELLO", true));
        assertFalse(dm.isDoubleMetaphoneEqual("hello", "world", true));
    }

    @Test
    public void testIsSilentStart() {
        DoubleMetaphone dm = new DoubleMetaphone();
        assertTrue(dm.isSilentStart("GN"));
        assertTrue(dm.isSilentStart("KN"));
        assertTrue(dm.isSilentStart("PN"));
        assertTrue(dm.isSilentStart("WR"));
        assertTrue(dm.isSilentStart("PS"));
        assertFalse(dm.isSilentStart("ABC"));
        assertFalse(dm.isSilentStart(""));
    }

    @Test
    public void testIsSlavoGermanic() {
        DoubleMetaphone dm = new DoubleMetaphone();
        assertTrue(dm.isSlavoGermanic("W"));
        assertTrue(dm.isSlavoGermanic("K"));
        assertTrue(dm.isSlavoGermanic("CZ"));
        assertTrue(dm.isSlavoGermanic("WITZ"));
        assertFalse(dm.isSlavoGermanic("ABC"));
        assertFalse(dm.isSlavoGermanic(""));
    }

    @Test
    public void testIsVowel() {
        DoubleMetaphone dm = new DoubleMetaphone();
        assertTrue(dm.isVowel('A'));
        assertTrue(dm.isVowel('E'));
        assertTrue(dm.isVowel('I'));
        assertTrue(dm.isVowel('O'));
        assertTrue(dm.isVowel('U'));
        assertTrue(dm.isVowel('Y'));
        assertFalse(dm.isVowel('B'));
        assertFalse(dm.isVowel('C'));
    }

    @Test
    public void testMaxCodeLen() {
        DoubleMetaphone dm = new DoubleMetaphone();
        assertEquals(4, dm.getMaxCodeLen());
        dm.setMaxCodeLen(5);
        assertEquals(5, dm.getMaxCodeLen());
    }

    @Test
    public void testHandleAEIOUY() {
        DoubleMetaphone dm = new DoubleMetaphone();
        DoubleMetaphone.DoubleMetaphoneResult result = new DoubleMetaphone.DoubleMetaphoneResult(4);
        int index = dm.handleAEIOUY(result, 0);
