    public void testGetFirst3Last3WithShortName() {
        assertEquals("JHN", encoder.getFirst3Last3("JHN"));
    }

    @Test
    public void testGetFirst3Last3WithLongName() {
        assertEquals("JHNSN", encoder.getFirst3Last3("Johnson"));
    }

