        assertEquals("english", lang.guessLanguage("HELLO"));
        assertEquals("english", lang.guessLanguage("Hello"));
    }

    @Test
    public void testEmptyInput() {
        assertEquals(Languages.ANY, lang.guessLanguage(""));
    }
}

