package org.apache.commons.codec.net;

import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.Test;

import java.nio.charset.StandardCharsets;
import java.nio.charset.UnsupportedCharsetException;

import static org.junit.Assert.*;

public class QCodecTest {

    private static final String TEST_STRING = "Hello World! This is a test string with special characters: @#$%^&*()";
    private static final String TEST_STRING_WITH_SPACES = "Hello World! This is a test string with   multiple   spaces";
    private static final String TEST_STRING_WITH_UNDERSCORES = "Hello_World!_This_is_a_test_string_with_underscores";
    private static final String TEST_STRING_WITH_NON_ASCII = "Hello World! This is a test string with non-ASCII characters: éèêë";

    @Test
    public void testDecodeNull() {
        QCodec codec = new QCodec();
        assertNull(codec.decode((Object) null));
    }

    @Test
    public void testDecodeNonString() {
        QCodec codec = new QCodec();
        try {
            codec.decode(123);
            fail("Expected DecoderException for non-String input");
        } catch (DecoderException e) {
            assertTrue(e.getMessage().contains("cannot be decoded using Q codec"));
        }
    }

    @Test
    public void testDecodeEmptyString() throws DecoderException {
        QCodec codec = new QCodec();
        assertEquals("", codec.decode(""));
    }

    @Test
    public void testDecodeWithUnderscores() throws DecoderException {
        QCodec codec = new QCodec();
        String encoded = "Hello=20World=21=20This=20is=20a=20test=20string=20with=20underscores=3A=20=5F=5F=5F";
        String decoded = codec.decode(encoded);
        assertEquals("Hello World! This is a test string with underscores: ___", decoded);
    }

    @Test
    public void testEncodeNull() {
        QCodec codec = new QCodec();
        assertNull(codec.encode((Object) null));
    }

    @Test
    public void testEncodeNonString() {
        QCodec codec = new QCodec();
        try {
            codec.encode(123);
            fail("Expected EncoderException for non-String input");
        } catch (EncoderException e) {
            assertTrue(e.getMessage().contains("cannot be encoded using Q codec"));
        }
    }

    @Test
    public void testEncodeEmptyString() throws EncoderException {
        QCodec codec = new QCodec();
        assertEquals("=?UTF-8?Q?=?=", codec.encode(""));
    }

    @Test
    public void testEncodeWithSpaces() throws EncoderException {
        QCodec codec = new QCodec();
        codec.setEncodeBlanks(true);
        String encoded = codec.encode(TEST_STRING_WITH_SPACES);
        assertTrue(encoded.contains("Hello_World=21_This_is_a_test_string_with___multiple___spaces"));
    }

    @Test
    public void testEncodeWithNonAscii() throws EncoderException {
        QCodec codec = new QCodec();
        String encoded = codec.encode(TEST_STRING_WITH_NON_ASCII);
        assertTrue(encoded.contains("Hello_World=21_This_is_a_test_string_with_non=2DASCII_characters=3A_=C3=A9=C3=A8=C3=A9=C3=A8"));
    }

    @Test
    public void testEncodeWithSpecialChars() throws EncoderException {
        QCodec codec = new QCodec();
        String encoded = codec.encode(TEST_STRING);
        assertTrue(encoded.contains("Hello_World=21_This_is_a_test_string_with_special_characters=3A_=40=23=24=25=5E=26=2A=28=29"));
    }

    @Test
    public void testRoundTripEncodingDecoding() throws EncoderException, DecoderException {
        QCodec codec = new QCodec();
        String encoded = codec.encode(TEST_STRING);
        String decoded = codec.decode(encoded);
        assertEquals(TEST_STRING, decoded);
    }

    @Test
    public void testRoundTripEncodingDecodingWithSpaces() throws EncoderException, DecoderException {
        QCodec codec = new QCodec();
        codec.setEncodeBlanks(true);
        String encoded = codec.encode(TEST_STRING_WITH_SPACES);
        String decoded = codec.decode(encoded);
        assertEquals(TEST_STRING_WITH_SPACES, decoded);
    }

    @Test
    public void testRoundTripEncodingDecodingWithUnderscores() throws EncoderException, DecoderException {
        QCodec codec = new QCodec();
        codec.setEncodeBlanks(true);
        String encoded = codec.encode(TEST_STRING_WITH_UNDERSCORES);
