    }

    @Test
    public void testRoundTripEncodingDecodingWithNonAscii() throws EncoderException, DecoderException {
        QCodec codec = new QCodec();
        String encoded = codec.encode(TEST_STRING_WITH_NON_ASCII);
        String decoded = codec.decode(encoded);
        assertEquals(TEST_STRING_WITH_NON_ASCII, decoded);
    }

    @Test
