        byte[] input = "Hello World!".getBytes();
        byte[] encoded = codec.encode(input);
        assertEquals("%48%65%6C%6C%6F%20%57%6F%72%6C%64%21", new String(encoded));
    }

    @Test
    public void testEncodeUrlWithSafeChars() {
        URLCodec codec = new URLCodec();
        byte[] input = "abc123.-_*".getBytes();
        byte[] encoded = codec.encode(input);
        assertEquals("abc123.-_*", new String(encoded));
    }

